# Register a service
curl -X PUT http://localhost:8500/v1/agent/service/register \
  -d '{
    "id": "user-service-1",
    "name": "user-service",
    "port": 8080,
    "check": {
      "http": "http://localhost:8080/health",
      "interval": "10s"
    }
  }'

# Query for healthy instances
curl http://localhost:8500/v1/health/service/user-service
